/* COSC 407/507 Lab 4, core A -- k3, three loops someone has already parallelised.
 *
 * *** DO NOT EDIT THIS FILE. *** You do not change any code in k3. You
 * measure it, and explain what you measured.
 *
 * Each loop is here twice: a plain serial version, and the OpenMP version.
 * Both compute the same thing; only the parallel version is timed against
 * threads.
 *
 *   bin/k3 WHICH [threads] [n]     WHICH = 1, 2 or 3
 *   bin/k3 2 0                     threads=0: the plain serial version
 *   bin/k3 2 4                     the OpenMP version on 4 threads
 *
 * ---------------------------------------------------------------------------
 * What the author believed:
 *
 *   "All three loops have independent iterations, all three are parallelised
 *    the textbook way, and all three print correct=yes at every thread count.
 *    So all three get faster with more threads -- on four cores, close to
 *    four times faster."
 *
 * One of the three is SLOWER with threads than without them, at every thread
 * count -- a net loss. Another gains far less than the thread count suggests.
 * ---------------------------------------------------------------------------
 *
 * time= in the output is the loop alone; setup= (making the input) is not in it.
 */
#include <string.h>

#include "lab4.h"

#define REPEAT 10                       /* loop 1 runs over its arrays this many times */

/* ---- loop 1: scale-and-add, a[i] = b[i] + 3 c[i], over three big arrays ---- */

static void loop1_serial(double *a, const double *b, const double *c, long n)
{
    for (int r = 0; r < REPEAT; r++)
        for (long i = 0; i < n; i++)
            a[i] = b[i] + 3.0 * c[i];
}

static void loop1_parallel(double *a, const double *b, const double *c, long n)
{
    for (int r = 0; r < REPEAT; r++) {
        #pragma omp parallel for
        for (long i = 0; i < n; i++)
            a[i] = b[i] + 3.0 * c[i];
    }
}

/* ---- loop 2: estimate pi by throwing n random darts at a square ---- */

static long loop2_serial(long n)
{
    long hits = 0;
    srand(1);
    for (long i = 0; i < n; i++) {
        double u = rand() / (RAND_MAX + 1.0);
        double v = rand() / (RAND_MAX + 1.0);
        if (u * u + v * v < 1.0) hits++;
    }
    return hits;
}

static long loop2_parallel(long n)
{
    long hits = 0;
    srand(1);
    #pragma omp parallel for reduction(+:hits)
    for (long i = 0; i < n; i++) {
        double u = rand() / (RAND_MAX + 1.0);
        double v = rand() / (RAND_MAX + 1.0);
        if (u * u + v * v < 1.0) hits++;
    }
    return hits;
}

/* ---- loop 3: a damped wave, summed over n points ---- */

static double loop3_serial(const double *x, long n)
{
    double sum = 0.0;
    for (long i = 0; i < n; i++)
        sum += exp(-x[i]) * cos(7.0 * x[i]);
    return sum;
}

static double loop3_parallel(const double *x, long n)
{
    double sum = 0.0;
    #pragma omp parallel for reduction(+:sum)
    for (long i = 0; i < n; i++)
        sum += exp(-x[i]) * cos(7.0 * x[i]);
    return sum;
}

/* ---------------------------------------------------------------------------- */

int main(int argc, char **argv)
{
    int which = argc > 1 ? atoi(argv[1]) : 0;
    if (which < 1 || which > 3) {
        fprintf(stderr, "usage: %s 1|2|3 [threads, 0 = serial] [n]\n", argv[0]);
        return 2;
    }
    static const long default_n[4] = { 0, 1L << 22, 1L << 23, 1L << 23 };
    lab4_args_t a = lab4_args(argc - 1, argv + 1, default_n[which]);
    char name[8];
    snprintf(name, sizeof name, "k3.%d", which);

    double t0, t1, t2, result = 0.0;
    int ok = 0;

    if (which == 1) {
        double *x = lab4_alloc(3 * (size_t)a.n * sizeof *x);
        double *A = x, *B = x + a.n, *C = x + 2 * a.n;
        t0 = lab4_now();
        lab4_fill_unit(B, a.n, 11);
        lab4_fill_unit(C, a.n, 12);
        memset(A, 0, (size_t)a.n * sizeof *A);
        t1 = lab4_now();
        if (a.threads == 0) loop1_serial(A, B, C, a.n);
        else                loop1_parallel(A, B, C, a.n);
        t2 = lab4_now();
        ok = 1;
        for (long i = 0; i < a.n; i++)
            if (A[i] != B[i] + 3.0 * C[i]) { ok = 0; break; }
        result = A[a.n / 2];
        free(x);
    } else if (which == 2) {
        t0 = t1 = lab4_now();
        long hits = a.threads == 0 ? loop2_serial(a.n) : loop2_parallel(a.n);
        t2 = lab4_now();
        result = 4.0 * (double)hits / (double)a.n;
        /* a fair estimate of pi is within 6 standard deviations, every time */
        ok = fabs(result - M_PI) <= 6.0 * 1.6421 / sqrt((double)a.n);
    } else {
        double *x = lab4_alloc((size_t)a.n * sizeof *x);
        t0 = lab4_now();
        lab4_fill_unit(x, a.n, 13);
        t1 = lab4_now();
        result = a.threads == 0 ? loop3_serial(x, a.n) : loop3_parallel(x, a.n);
        t2 = lab4_now();
        ok = lab4_close(result, loop3_serial(x, a.n));
        free(x);
    }

    lab4_report(name, a, t1 - t0, t2 - t1, t2 - t1, result, ok);
    return ok ? 0 : 1;
}
